package test;

import org.eclipse.jdt.core.ICompilationUnit;
import org.eclipse.jdt.core.IType;
import org.eclipse.jdt.core.JavaModelException;

public class TestClass {
    // Assume IType.getCompilationUnit() can return null for binary types.
    public void checkVisibility(IType type, ICompilationUnit currentUnit) throws JavaModelException {
        // Problematic pattern: If type.getCompilationUnit() is null, calling .equals() will throw NPE.
        if (type.getCompilationUnit().equals(currentUnit)) {
            System.out.println("Same unit");
        }
    }
}

afterExample:
package test;

import org.eclipse.jdt.core.ICompilationUnit;
import org.eclipse.jdt.core.IType;
import org.eclipse.jdt.core.JavaModelException;

public class TestClass {
    // Assume IType.getCompilationUnit() can return null for binary types.
    public void checkVisibility(IType type, ICompilationUnit currentUnit) throws JavaModelException {
        // Fixed pattern: currentUnit (assumed non-null) handles null argument gracefully.
        if (currentUnit.equals(type.getCompilationUnit())) {
            System.out.println("Same unit");
        }
    }
}

negativeExample:
package test;

import org.eclipse.jdt.core.ICompilationUnit;
import org.eclipse.jdt.core.IType;
import org.eclipse.jdt.core.JavaModelException;

public class TestClass {
    public void checkVisibility(IType type, ICompilationUnit currentUnit) throws JavaModelException {
        // Not matching: direct equals() on objects (not a method call to getCompilationUnit())
        if (type.equals(currentUnit)) {
            System.out.println("Direct equals");
        }

        // Not matching: a different method call (not getCompilationUnit())
        if (type.getJavaProject().equals(currentUnit.getJavaProject())) {
            System.out.println("Different method");
        }

        // Not matching: a null check, not an equals() call on a potentially null receiver
        if (type.getCompilationUnit() == null) {
            System.out.println("Null check");
        }
    }
}
